/**
 * Builds functions/src/trendVocabulary.ts: the pieces the app can actually
 * show, as plain retail phrases, with how many photographed pieces carry
 * each one per department.
 *
 * The weekly trend generator (functions: refreshTrendList) may only name
 * key garments and accessories from this list. That is what guarantees an
 * auto-generated trend arrives with real, photo-checked pieces under it and
 * links that search for the right thing - a trend written in words no
 * product uses ("laser-cut shirt") can no longer be produced.
 *
 * Phrases are read off the catalogue itself (product names and
 * subcategories), so the client's matcher - a substring test over the same
 * fields - finds every one of them by construction.
 *
 * Run after ANY catalogue change:  npx tsx scripts/buildTrendVocabulary.ts
 * (scripts/auditTrendPath.ts fails when the committed file is out of date.)
 */

import fs from 'fs';
import path from 'path';
import { BALANCED_CATALOG } from '../src/data/mockProductCatalog';
import { slotOf } from '../src/services/trendLooks';

export interface VocabularyTerm {
  term: string;
  slot: 'garment' | 'shoes' | 'finish';
  women: number;
  men: number;
}

/** Words that describe a piece without naming it - never a term on their own or at its end. */
const NOT_A_NOUN = new Set([
  'and', 'with', 'in', 'the', 'of', 'set', 'leather', 'suede', 'linen', 'wool', 'cotton', 'silk', 'knit', 'canvas',
  'print', 'printed', 'striped', 'floral', 'classic', 'relaxed', 'oversized', 'cropped', 'slim', 'wide', 'long',
  'short', 'high', 'low', 'mini', 'midi', 'maxi', 'black', 'white', 'brown', 'navy', 'blue', 'green', 'red', 'tan',
  'cream', 'beige', 'grey', 'gold', 'silver', 'burgundy', 'oxblood', 'pink', 'olive', 'camel',
]);

/** Cuts that fall mid-phrase and name no piece on their own. */
const FRAGMENTS = new Set([
  'leg jeans', 'oxford dress', 'long sleeve', 'puff sleeve', 'sleeve top', 'jane flats', 'built-in bra',
  'collar shirt', 'halter tank', 'knit top',
]);

const MIN_PIECES = 2;
const MAX_TERMS = 280;

export function buildVocabulary(): VocabularyTerm[] {
  const wordsOf = (field: string) => field.toLowerCase().replace(/[^a-z0-9' -]/g, ' ').split(/\s+/).filter(Boolean);
  // What a piece IS: the last word of a product name ("loafers", "blazer", "scarf").
  const nouns = new Set(BALANCED_CATALOG.map(p => wordsOf(p.name).pop() || '').filter(w => w.length > 2 && !NOT_A_NOUN.has(w)));
  const noun = (word: string) => nouns.has(word) || nouns.has(`${word}s`);

  const seen = new Map<string, { women: Set<string>; men: Set<string>; slots: Record<string, number> }>();
  for (const product of BALANCED_CATALOG) {
    const grams = new Set<string>();
    // Names are clean product phrases. A subcategory is used only when it is
    // one phrase - longer ones are several phrases side by side, and a term
    // cut across two of them ("bag top-handle") names nothing.
    const sub = wordsOf(product.subcategory || '');
    for (const words of [wordsOf(product.name), sub.length <= 3 ? sub : []]) {
      // Two or three words, ending on the piece. Single words ("jacket",
      // "shirt") are left out on purpose: a trend anchored on one would
      // match half the catalogue and illustrate nothing in particular.
      for (let n = 2; n <= 3; n++) {
        for (let i = 0; i + n <= words.length; i++) {
          const gram = words.slice(i, i + n);
          if (!noun(gram[gram.length - 1]) || NOT_A_NOUN.has(gram[gram.length - 1])) continue;
          if (['and', 'with', 'in', 'the', 'of', '-'].includes(gram[0])) continue;
          grams.add(gram.join(' '));
        }
      }
    }
    const women = product.department !== 'men';
    const men = product.department !== 'women';
    for (const gram of grams) {
      const entry = seen.get(gram) ?? { women: new Set<string>(), men: new Set<string>(), slots: {} };
      if (women) entry.women.add(product.id);
      if (men) entry.men.add(product.id);
      const slot = slotOf(product);
      entry.slots[slot] = (entry.slots[slot] || 0) + 1;
      seen.set(gram, entry);
    }
  }

  return [...seen.entries()]
    .map(([term, e]) => ({
      term,
      slot: Object.entries(e.slots).sort((a, b) => b[1] - a[1])[0][0] as VocabularyTerm['slot'],
      women: e.women.size,
      men: e.men.size,
    }))
    .filter(v => Math.max(v.women, v.men) >= MIN_PIECES && !FRAGMENTS.has(v.term))
    // Specific phrases first (they make sharper trends), then the most illustrated.
    .sort((a, b) => b.term.split(' ').length - a.term.split(' ').length || b.women + b.men - (a.women + a.men) || a.term.localeCompare(b.term))
    .slice(0, MAX_TERMS)
    .sort((a, b) => a.slot.localeCompare(b.slot) || a.term.localeCompare(b.term));
}

export function renderVocabulary(terms: VocabularyTerm[]): string {
  return `/**
 * GENERATED by scripts/buildTrendVocabulary.ts - do not edit by hand.
 *
 * The pieces the app can show, as retail phrases, with the number of
 * photographed pieces carrying each one for a womenswear and a menswear
 * reader. The weekly trend generator may only name pieces from this list.
 */
export interface TrendVocabularyTerm {
  term: string;
  slot: 'garment' | 'shoes' | 'finish';
  women: number;
  men: number;
}

export const TREND_VOCABULARY: TrendVocabularyTerm[] = [
${terms.map(v => `  { term: ${JSON.stringify(v.term)}, slot: '${v.slot}', women: ${v.women}, men: ${v.men} },`).join('\n')}
];
`;
}

if (require.main === module) {
  const terms = buildVocabulary();
  const out = path.join(__dirname, '../functions/src/trendVocabulary.ts');
  fs.writeFileSync(out, renderVocabulary(terms));
  const by = (slot: string) => terms.filter(t => t.slot === slot).length;
  console.log(`wrote ${terms.length} terms (garment ${by('garment')}, shoes ${by('shoes')}, finish ${by('finish')}) to functions/src/trendVocabulary.ts`);
}
